     */
    @Transactional
    public InvoiceDetailResponse releaseRetention(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() == InvoiceStatus.DRAFT || invoice.getStatus().isClosedUnpaid()) {
